import math
import re

_TOKEN_RE = re.compile(
    r"""
    \s*(?:
        (?P<number>(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)
      | (?P<op>\*\*|[+\-*/])
      | (?P<lparen>\()
      | (?P<rparen>\))
    )
    """,
    re.VERBOSE,
)


def _tokenize(expression):
    tokens = []
    pos = 0
    length = len(expression)
    while pos < length:
        if expression[pos].isspace():
            pos += 1
            continue
        match = _TOKEN_RE.match(expression, pos)
        if not match or match.end() == pos:
            raise ValueError(
                f"Invalid character {expression[pos]!r} at position {pos}"
            )
        if match.group("number") is not None:
            tokens.append(("number", match.group("number")))
        elif match.group("op") is not None:
            tokens.append(("op", match.group("op")))
        elif match.group("lparen") is not None:
            tokens.append(("lparen", "("))
        elif match.group("rparen") is not None:
            tokens.append(("rparen", ")"))
        pos = match.end()
    return tokens


class _Parser:
    # Grammar:
    #   expr    := term (('+' | '-') term)*
    #   term    := unary (('*' | '/') unary)*
    #   unary   := ('+' | '-') unary | power
    #   power   := primary ('**' unary)?
    #   primary := NUMBER | '(' expr ')'

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _advance(self):
        tok = self._peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        self.pos += 1
        return tok

    def parse(self):
        if not self.tokens:
            raise ValueError("Empty expression")
        value = self._expr()
        if self._peek() is not None:
            raise ValueError(f"Unexpected token {self._peek()[1]!r}")
        return value

    def _expr(self):
        value = self._term()
        while True:
            tok = self._peek()
            if tok is not None and tok[0] == "op" and tok[1] in ("+", "-"):
                self._advance()
                rhs = self._term()
                value = value + rhs if tok[1] == "+" else value - rhs
            else:
                return value

    def _term(self):
        value = self._unary()
        while True:
            tok = self._peek()
            if tok is not None and tok[0] == "op" and tok[1] in ("*", "/"):
                self._advance()
                rhs = self._unary()
                if tok[1] == "*":
                    value = value * rhs
                else:
                    if rhs == 0:
                        raise ValueError("Division by zero")
                    value = value / rhs
            else:
                return value

    def _unary(self):
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] in ("+", "-"):
            self._advance()
            operand = self._unary()
            return -operand if tok[1] == "-" else operand
        return self._power()

    def _power(self):
        base = self._primary()
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] == "**":
            self._advance()
            exponent = self._unary()  # right-associative; allows 2 ** -1
            try:
                result = base ** exponent
            except OverflowError:
                raise ValueError("Numeric overflow")
            except ZeroDivisionError:
                raise ValueError("Division by zero")
            if isinstance(result, complex):
                raise ValueError("Result is not a real number")
            return result
        return base

    def _primary(self):
        tok = self._advance()
        kind, text = tok
        if kind == "number":
            try:
                return float(text)
            except ValueError:
                raise ValueError(f"Invalid number {text!r}")
        if kind == "lparen":
            value = self._expr()
            closing = self._peek()
            if closing is None or closing[0] != "rparen":
                raise ValueError("Missing closing parenthesis")
            self._advance()
            return value
        raise ValueError(f"Unexpected token {text!r}")


def evaluate_expression(expression: str) -> float:
    """Evaluate an arithmetic expression such as "2 * (3 + 4) - 1.5" and return the
    result as a float. Numbers, parentheses, unary minus and the operators + - * / **
    are supported. Raise ValueError for malformed input such as "2 +" or an empty string.
    """
    if not isinstance(expression, str):
        raise ValueError("Expression must be a string")
    if expression.strip() == "":
        raise ValueError("Empty expression")
    try:
        tokens = _tokenize(expression)
        result = _Parser(tokens).parse()
    except RecursionError:
        raise ValueError("Expression nested too deeply")
    result = float(result)
    if not math.isfinite(result):
        raise ValueError("Result is not finite")
    return result
